module MenhirInterpreter = struct
  
  module ET = MenhirLib.TableInterpreter.MakeEngineTable (Tables)
  
  module TI = MenhirLib.Engine.Make (ET)
  
  include TI
  
end

let prog =
  fun lexer lexbuf : (EcParsetree.prog) ->
    Obj.magic (MenhirInterpreter.entry `Legacy 7346 lexer lexbuf)

and is_uniop =
  fun lexer lexbuf : (unit) ->
    Obj.magic (MenhirInterpreter.entry `Legacy 7336 lexer lexbuf)

and is_numop =
  fun lexer lexbuf : (unit) ->
    Obj.magic (MenhirInterpreter.entry `Legacy 7332 lexer lexbuf)

and is_binop =
  fun lexer lexbuf : (unit) ->
    Obj.magic (MenhirInterpreter.entry `Legacy 7280 lexer lexbuf)

and global =
  fun lexer lexbuf : (EcParsetree.global) ->
    Obj.magic (MenhirInterpreter.entry `Legacy 0 lexer lexbuf)

module Incremental = struct
  
  let prog =
    fun initial_position : (EcParsetree.prog) MenhirInterpreter.checkpoint ->
      Obj.magic (MenhirInterpreter.start 7346 initial_position)
  
  and is_uniop =
    fun initial_position : (unit) MenhirInterpreter.checkpoint ->
      Obj.magic (MenhirInterpreter.start 7336 initial_position)
  
  and is_numop =
    fun initial_position : (unit) MenhirInterpreter.checkpoint ->
      Obj.magic (MenhirInterpreter.start 7332 initial_position)
  
  and is_binop =
    fun initial_position : (unit) MenhirInterpreter.checkpoint ->
      Obj.magic (MenhirInterpreter.start 7280 initial_position)
  
  and global =
    fun initial_position : (EcParsetree.global) MenhirInterpreter.checkpoint ->
      Obj.magic (MenhirInterpreter.start 0 initial_position)
  
end
